def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n, k = int(input[ptr]), int(input[ptr+1])
    ptr += 2
    problems = []
    for _ in range(n):
        row = list(map(int, input[ptr:ptr+k]))
        ptr += k
        problems.append(row)

    for mask in range(1, 1 << n):
        total = bin(mask).count('1')
        if total == 0:
            continue
        valid = True
        for team in range(k):
            known = 0
            for i in range(n):
                if (mask & (1 << i)) and problems[i][team]:
                    known += 1
            if known > total // 2:
                valid = False
                break
        if valid:
            print("YES")
            return
    print("NO")

solve()
